CREATE TABLE "CuentasBancarias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_CuentasBancarias" PRIMARY KEY,
    "Banco" character varying(120) NOT NULL,
    "Numero" character varying(40) NOT NULL,
    "Nombre" character varying(120) NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "Moneda" character(3) NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "CK_CuentasBancarias_Textos" CHECK (
        "Banco" = btrim("Banco") AND "Banco" <> '' AND "Numero" = btrim("Numero") AND "Numero" <> '' AND btrim("Nombre") <> ''),
    CONSTRAINT "CK_CuentasBancarias_Tipo" CHECK ("Tipo" IN ('Corriente', 'Ahorros')),
    CONSTRAINT "CK_CuentasBancarias_Moneda" CHECK ("Moneda" IN ('PEN', 'USD'))
);
CREATE UNIQUE INDEX "IX_CuentasBancarias_BancoNumero" ON "CuentasBancarias" ("Banco", "Numero");
CREATE INDEX "IX_CuentasBancarias_MonedaTipo" ON "CuentasBancarias" ("Moneda", "Tipo");

CREATE TABLE "TransferenciasBancarias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_TransferenciasBancarias" PRIMARY KEY,
    "CuentaOrigenId" integer NOT NULL,
    "CuentaDestinoId" integer NOT NULL,
    "Importe" numeric(18,2) NOT NULL,
    "FechaOperacion" date NOT NULL,
    "Referencia" character varying(100),
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "FK_TransferenciasBancarias_CuentaOrigen" FOREIGN KEY ("CuentaOrigenId") REFERENCES "CuentasBancarias" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_TransferenciasBancarias_CuentaDestino" FOREIGN KEY ("CuentaDestinoId") REFERENCES "CuentasBancarias" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_TransferenciasBancarias_CuentasDistintas" CHECK ("CuentaOrigenId" <> "CuentaDestinoId"),
    CONSTRAINT "CK_TransferenciasBancarias_Importe" CHECK ("Importe" > 0 AND "Importe" <> 'NaN'::numeric)
);
CREATE INDEX "IX_TransferenciasBancarias_CuentaOrigenId" ON "TransferenciasBancarias" ("CuentaOrigenId");
CREATE INDEX "IX_TransferenciasBancarias_CuentaDestinoId" ON "TransferenciasBancarias" ("CuentaDestinoId");

CREATE TABLE "MovimientosBancarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_MovimientosBancarios" PRIMARY KEY,
    "CuentaBancariaId" integer NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "Importe" numeric(18,2) NOT NULL,
    "FechaOperacion" date NOT NULL,
    "Referencia" character varying(100),
    "TransferenciaBancariaId" integer,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT now(),
    "FechaReversion" timestamp with time zone,
    "MotivoReversion" character varying(300),
    CONSTRAINT "FK_MovimientosBancarios_CuentaBancaria" FOREIGN KEY ("CuentaBancariaId") REFERENCES "CuentasBancarias" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MovimientosBancarios_TransferenciaBancaria" FOREIGN KEY ("TransferenciaBancariaId") REFERENCES "TransferenciasBancarias" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_MovimientosBancarios_Tipo" CHECK ("Tipo" IN ('Ingreso', 'Egreso')),
    CONSTRAINT "CK_MovimientosBancarios_Importe" CHECK ("Importe" > 0 AND "Importe" <> 'NaN'::numeric),
    CONSTRAINT "CK_MovimientosBancarios_Reversion" CHECK (
        ("FechaReversion" IS NULL AND "MotivoReversion" IS NULL)
        OR ("TransferenciaBancariaId" IS NULL AND "FechaReversion" IS NOT NULL AND "MotivoReversion" IS NOT NULL
            AND char_length(btrim("MotivoReversion")) BETWEEN 3 AND 300))
);
CREATE INDEX "IX_MovimientosBancarios_CuentaFechaId" ON "MovimientosBancarios" ("CuentaBancariaId", "FechaOperacion" DESC, "Id" DESC);
CREATE UNIQUE INDEX "IX_MovimientosBancarios_TransferenciaTipo" ON "MovimientosBancarios" ("TransferenciaBancariaId", "Tipo");
